import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}function extrude(parent,s,depth,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){const s=new THREE.Shape();s.moveTo(-10.4,-12);s.lineTo(-8.8,-14);s.lineTo(-5.5,-14);s.lineTo(-5.5,-8.2);s.lineTo(5.5,-8.2);s.lineTo(5.5,-14);s.lineTo(8.8,-14);s.lineTo(10.4,-12);s.lineTo(10.4,-7.6);s.lineTo(8,-7.6);s.absarc(8,-4,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-.4);s.lineTo(10.4,12.3);s.lineTo(8.5,14.3);s.lineTo(-8.5,14.3);s.lineTo(-10.4,12.3);s.lineTo(-10.4,-.4);s.lineTo(-8,-.4);s.absarc(-8,-4,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-7.6);s.closePath();hole(s,0,-4,2.1);const pcb=extrude(host.body,s,.8,[0,0,-.8],materials.plastic(0x202821,{roughness:.88}),'BLDC Driver fixed PCB with real mounting reliefs and central retaining bore');pcb.userData.role='physical-pcb';const metal=materials.metal(0xb6bba9,{roughness:.49}),dark=materials.plastic(0x21241f,{roughness:.86}),ceramic=materials.plastic(0xaaa07b,{roughness:.86}),packages=[];
 const ic=(x,y,w,h,n,leads)=>{const body=slab(host.body,w,h,1,.13,[x,y,.08],dark,[],.02);body.name='BLDC Driver '+n;packages.push(body);for(const sign of[-1,1])for(let i=0;i<leads;i++)mesh(host.body,new THREE.BoxGeometry(.8,.27,.16),metal,[x+sign*(w/2+.25),y+(i-(leads-1)/2)*.55,.18],n+' physical lead');return body;};const mcu=ic(-4.2,4.5,4.4,6.2,'U1 STM32G030F6P6 fixed package',10),driver=ic(4.2,5.5,4.4,5.2,'U3 DRV11873PWPR fixed package',8);
 const passives=[];for(const [i,x,y]of[[1,-8,10.8],[2,-8,8.5],[3,-8,6.2],[4,-7.8,2],[5,-2.3,11],[6,.1,11],[7,2.5,11],[8,7.7,.9],[9,4.9,-.8],[10,2.6,-.8],[11,0.2,-.8],[12,-2.2,-.8]]){passives.push(mesh(host.body,new THREE.BoxGeometry(1.6,.9,.7),i<5?dark:ceramic,[x,y,.4],'BLDC Driver fixed capacitor resistor package '+i));for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.28,.9,.72),metal,[x+sign*.66,y,.4],'BLDC Driver passive solder end');}for(const x of[-5.8,-2.6,.6]){mesh(host.body,new THREE.BoxGeometry(2.1,1.3,.9),dark,[x,13,.5],'BLDC Driver fixed SS16-A diode');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.35,1.3,.3),metal,[x+sign*1.0,13,.2],'BLDC Driver diode termination');}
 const pads=[];for(let i=0;i<5;i++){const shape=new THREE.Shape();shape.absarc(0,0,.55,0,tau,false);pads.push(extrude(host.body,shape,.035,[-7.5+i*1.75,-9.2,.005],materials.metal(0xc6a947,{roughness:.51}),'BLDC Driver concealed J3 upgrade pad '+(i+1)));}
 const ledBase=mesh(host.body,new THREE.BoxGeometry(1.6,.85,.45),materials.plastic(0xe4e5d8,{roughness:.72}),[-7.8,1.8,.25],'BLDC Driver concealed D1 SYS_LED substrate');const hiddenLed=mesh(host.body,new THREE.BoxGeometry(.9,.65,.16),materials.plastic(0x518852,{roughness:.45}),[-7.8,1.8,.555],'BLDC Driver concealed green SYS_LED resin,non-emissive');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,.85,.35),metal,[-7.8+sign*.7,1.8,.18],'BLDC Driver concealed D1 solder end');return{pcb,mcu,driver,packages,passives,pads,ledBase,hiddenLed};}
export function buildBLDCDriver(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe9eae5,{roughness:.78})}),pcb=board(host),input=grove(host),output=terminal(host),fixing=screw(host.body,[0,-4,-3.01],'back',1.55);fixing.name='BLDC Driver fixed recessed rear hex screw';fixing.traverse(o=>{if(o.isMesh)o.name='BLDC Driver fixed hex retaining screw face';});mesh(host.body,new THREE.CylinderGeometry(.65,.65,3.5,32).rotateX(Math.PI/2),materials.metal(0x9ca093),[0,-4,-1.2],'BLDC Driver concealed fixed screw shank');const labelCarrier=slab(host.body,16.2,12.2,.1,.04,[0,7,-4],materials.plastic(0xdce1dc,{roughness:.86}),[],.005);labelCarrier.name='BLDC Driver physical rear adhesive label substrate over native label recess';host.bldcDriverAssembly={parts,pcb,input,output,fixing,labelCarrier};host.unitStickers=addStickers(host);}
